// Globals injected by the Electron Forge Vite plugin at build time (one pair per
// renderer name). Guarded with `typeof` checks at runtime so the main process
// also runs outside Forge.
declare const CONTROL_VITE_DEV_SERVER_URL: string | undefined;
declare const CONTROL_VITE_NAME: string | undefined;
declare const STAGE_VITE_DEV_SERVER_URL: string | undefined;
declare const STAGE_VITE_NAME: string | undefined;
